begin;
select plan(32);
select has_column('public','patients','wristband_barcode','patients can be matched to scanned wristbands');
select has_table('public','mar_scheduled_doses','each MAR event refers to an individually scheduled dose');
select has_table('public','mar_facility_settings','administration time windows are facility configured');
select has_table('public','mar_witness_credentials','second nurse witnesses authenticate with a PIN');
select has_column('public','medication_administrations','scheduled_dose_id','administrations are linked to a scheduled dose');
select has_column('public','medication_administrations','inventory_lot_id','administrations retain the scanned stock lot');
select has_column('public','medication_administrations','witnessed_by','witness identity is retained');
select has_function('public','record_mar_dose',array['uuid','text','text','numeric','text','text','text','text','boolean','uuid','text'],'administration and non-administration outcomes are server verified');
select has_function('public','schedule_mar_dose',array['uuid','timestamp with time zone'],'doses are scheduled from prescribed items');
select has_function('public','set_mar_witness_pin',array['text'],'nurses can set their own witness PIN');
select has_function('public','configure_mar_time_window',array['uuid','integer','integer'],'facility administrators configure medication time windows');
select has_function('public','set_patient_wristband_barcode',array['uuid','text'],'nurses can enroll wristband barcodes');
select ok(not has_table_privilege('authenticated','public.medication_administrations','INSERT'),'clients cannot bypass the verified administration RPC');
select ok(not has_table_privilege('authenticated','public.mar_scheduled_doses','UPDATE'),'scheduled dose outcomes cannot be edited directly');
select has_trigger('public','mar_scheduled_doses','mar_scheduled_doses_immutable','scheduled-dose history is controlled by the MAR workflow');
select has_trigger('public','medication_administrations','medication_administrations_mar_immutable','administration records are immutable');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%Patient wristband barcode does not match%','wrong patient barcode is rejected');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%does not match the prescribed formulary item%','wrong medication barcode is rejected');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%expired or has no expiry date%','expired lots are rejected');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%Active confirmed medication allergy conflicts%','active allergy conflicts are rejected unless witnessed override is supplied');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%does not match the prescribed scheduled dose%','wrong dose is rejected');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%does not match the prescribed route%','wrong route is rejected');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%outside the configured administration time window%','outside-window administration is rejected');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%Medication/lot barcode was not found%','unknown lot barcode is rejected');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%lot is unavailable for administration%','inactive or depleted lot is rejected');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%An override reason is required%','override without a reason is rejected');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%A second nurse witness and PIN are required%','override or controlled drug without a witness is rejected');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%Second nurse witness PIN is invalid%','incorrect second nurse PIN is rejected');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'%A reason is required for a missed, held, or refused dose%','missed/held/refused dose without a reason is rejected');
select like(pg_get_functiondef('public.record_mar_dose(uuid,text,text,numeric,text,text,text,text,boolean,uuid,text)'::regprocedure),'witness_required:=item.controlled or p_override','controlled drugs always require a second nurse witness');
select throws_ok($$select public.record_mar_dose(null,null,null,null,null,null)$$,'P0001','Only an active nurse may record MAR doses.','unauthenticated callers cannot record a dose');
select throws_ok($$select public.set_mar_witness_pin('123456')$$,'P0001','Only an active nurse may set a MAR witness PIN.','unauthenticated callers cannot set witness credentials');
select * from finish();
rollback;
